INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('03eee90f-68db-4738-8260-19e3a14c2e5a', 'Fecha de Apertura', '30 de mayo de 2022', 'America Gonzalez', NULL);
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('03eee90f-68db-4738-8260-19e3a14c2e5a', 'Incremento de Renta', '12', '5', 'INCREMENTOS DE RENTA', E'- The rent can only increase every 12 months, starting from the date rent payments begin.\n- The increase will match the inflation rate in Mexico, based on the National Consumer Price Index by INEGI or a similar source.\n- The rent increase cannot exceed 5% for the tenant.\n- At the start of the seventh year, the new minimum monthly rent will be based on the average monthly rent paid in the previous year, including any percentage rent.\n- This new rent amount will continue to be subject to annual increases.\n- The tenant must also pay any agreed percentage rent.', E'Solo podrá incrementarse cada 12 (doce) meses, contados a partir de la fecha de inicio de pago de renta, aumentará la Renta Mensual Mínima Garantizada en la misma proporción que sufra la inflación de los Estados Unidos Mexicanos, para lo cual se tomará como base el Índice Nacional de Precios al Consumidor publicado por el Instituto Nacional de Estadística y Geografía (INEGI) o cualquier otro autorizado para publicarlo durante los 12 (doce) meses anteriores o el que lo sustituya. No obstante lo anterior, las Partes acuerdan que el incremento aplicable a la Renta no podrá exceder del 5% (cinco por ciento) para el "ARRENDATARIO".\n\nAl inicio del séptimo año de vigencia, la nueva Renta Mensual Mínima Garantizada aplicable a partir de ese momento se calculará tomando como base la Renta Mensual pagada durante el año anterior, considerando como Renta Mensual y su integración (incluye Renta Porcentual), se obtendrá un promedio mensual y el monto que resulte, se determinará como la Renta Mensual Mínima Garantizada pagadera a partir del séptimo año de vigencia, a cuyo monto se seguirán aplicando los incrementos anuales. Con independencia de la obligación de pago de la Renta Porcentual convenida.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('03eee90f-68db-4738-8260-19e3a14c2e5a', 'Late Fees', '12', '6', 'INTERÉS MORATORIO', E'- If the tenant doesn''t pay the agreed rent or any other amount on time, they will owe late interest. This interest is 8% of the unpaid balance, calculated monthly until fully paid.\n- The landlord can accept rent payments and apply them to the oldest debts first. The order of payment application is: late interest, maintenance fees, minimum guaranteed rent or percentage rent, and then any other outstanding amounts.', E'Para el caso de que el "ARRENDATARIO", no pague la Renta Mensual Mínima Garantizada y/o Renta Porcentual y/o cualquier cantidad a su cargo dentro del término pactado para ello, pagará por concepto de intereses moratorios a favor del "ARRENDADOR" la cantidad que resulte de multiplicar el 8% (ocho) por ciento por el monto de los saldos insolutos, de manera mensual desde su constitución en mora y hasta la total liquidación.\n\nEl "ARRENDADOR" podrá recibir el pago de la Renta Mensual Mínima Garantizada y/o Renta Porcentual o por cualquier otro concepto, y si fuera el caso de que el "ARRENDATARIO" no ha cubierto el pago de la Renta Mensual Mínima Garantizada y/o Renta Porcentual y/o cualquier otra cantidad adeudada bajo este Contrato a que se encuentre obligado a pagar, el "ARRENDADOR" tendrá la facultad de recibir dicho pago y aplicarlo para cubrir el adeudo más antiguo primero por intereses moratorios, y posteriormente a la Cuota de Mantenimiento, después a la Renta Mensual Mínima Garantizada y/o Renta Porcentual y después a cualquier otro concepto pendiente de pago.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('03eee90f-68db-4738-8260-19e3a14c2e5a', 'Percentage Rent', '9', '3', 'PRECIO', E'- The tenant must calculate monthly net income for the entire lease term.\n- In addition to the guaranteed minimum monthly rent, the tenant will pay a percentage rent.\n- The percentage rent is calculated as 14% of the monthly net income minus the guaranteed minimum monthly rent, plus applicable VAT.\n- The tenant pays the percentage rent if 14% of the net income exceeds the guaranteed minimum monthly rent.\n- The total rent includes both the guaranteed minimum monthly rent and the percentage rent.\n- If percentage rent is due, it must be paid with the next month''s guaranteed minimum monthly rent.', E'El "ARRENDATARIO" estará obligado a calcular cada mes y durante toda la vigencia del presente Contrato, el total de los Ingresos Netos realizadas en el Local para los siguientes efectos:\n\nEn adición a la Renta Mensual Mínima Garantizada, el "ARRENDATARIO" pagará mensualmente y durante toda la vigencia del presente Contrato al "ARRENDADOR" una Renta Porcentual que será la cantidad equivalente que resulte de restar la Renta Mensual Mínima Garantizada al resultado de multiplicar el 14% por los Ingresos Netos del mes que corresponda más el correspondiente al Impuesto al Valor Agregado (en lo sucesivo la "Renta Porcentual").\n\nEl "ARRENDATARIO" pagará la Renta Porcentual, si el 14% multiplicado por los Ingresos Netos que se hayan generado durante el mes que corresponda es superior a la Renta Mensual Mínima Garantizada pagada. En el entendido de que la suma total de la Renta Mensual Mínima Garantizada y la Renta Porcentual se considerará en su conjunto para efectos de este Contrato como la Renta Mensual a pagar por parte del "ARRENDATARIO".\n\nSi el "ARRENDATARIO" tuviere que pagar Renta Porcentual durante la vigencia del presente Contrato, derivado de las Ventas Netas que generado, el monto de la Renta Porcentual del mes que corresponda (o de ambos en su caso) deberá ser liquidado al "ARRENDADOR" junto con la Renta Mensual Mínima Garantizada del siguiente mes en la fecha en que el pago de la Renta Mensual Mínima Garantizada sea exigible.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('03eee90f-68db-4738-8260-19e3a14c2e5a', 'Common Area Maintenance Charges', '28', '20', 'MANTENIMIENTO', E'- El arrendatario debe pagar al arrendador o al administrador del centro comercial las cuotas de mantenimiento.\n- La cuota inicial es de $79,750.00 más el IVA.\n- El pago debe comenzar desde la fecha de inicio del pago de la renta.\n- Los intereses por pagos tardíos se aplicarán de la misma manera que para la renta mensual mínima.', E'El "ARRENDATARIO" se obliga a pagar al "ARRENDADOR" y/o al Administrador el Centro Comercial que para tal efecto le indique por escrito, las cantidades que le corresponden por cuotas de mantenimiento siendo la cantidad inicial de $79,750.00 más el Impuesto al Valor Agregado, obligándose a su pago a partir de la fecha de inicio de pago de renta.\n\nLos intereses moratorios y la actualización se harán en los mismos términos y condiciones que la Renta Mensual Mínima.');
