INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('4fa4c901-7878-42bd-be24-d588310b051a', 'Late Fees', '13', '8', 'RENTA Y FORMA DE PAGO', E'- If the subtenant doesn''t pay the monthly rent on time, they will be charged a penalty.\n- The penalty is 5% of the unpaid rent balance.\n- This penalty applies for each month the rent remains unpaid until the full amount is paid.', 'La falta de pago puntual de la RENTA MENSUAL de que se trate generará a cargo de LA SUBARRENTARIA una pena convencional equivalente al 5% (cinco por ciento) sobre el saldo insoluto de la RENTA MENSUAL, por cada mes de retraso en el pago de la RENTA MENSUAL y hasta en tanto dicho saldo insoluto no sea pagado en su totalidad.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('4fa4c901-7878-42bd-be24-d588310b051a', 'Common Area Maintenance Charges', '12', '8', 'RENTA Y FORMA DE PAGO', E'- The subtenant agrees to pay the sublandlord a monthly rent of $362,045.00.\n- This amount is subject to additional Value Added Tax (VAT).\n- The rent includes the maintenance fee for the shopping center.', 'LA SUBARRENTARIA se obliga a pagar a EL SUBARRENDADOR por concepto de renta, la cantidad de $362,045.00 (trescientos sesenta y dos mil cuarenta y cinco pesos 00/100 M.N.), más Impuesto al Valor Agregado correspondiente (en lo sucesivo la "RENTA MENSUAL"), misma que incluye la cuota de mantenimiento del Centro Comercial.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('4fa4c901-7878-42bd-be24-d588310b051a', 'Incremento de Renta', '12', '8', 'RENTA Y FORMA DE PAGO', E'- After one year from the Rent Payment Start Date, and annually thereafter, the Monthly Rent will increase based on the percentage increase of the National Consumer Price Index (INPC) from the previous 12 months.\n- The increase cannot exceed 10%.\n- If the increase is more than 16%, both parties will meet to agree on the new rent amount.', 'Transcurrido un año a partir de la Fecha de Inicio de Pago de la Renta y posteriormente de manera anual, la RENTA MENSUAL serán incrementadas anualmente en el mismo porcentaje de incremento que se haya registrado durante los últimos 12 (doce) meses inmediatos anteriores, el Índice Nacional de Precios al Consumidor (INPC) que publica el Instituto Nacional de Estadísticas y Geografía (INEGI). En la inteligencia de que dichos aumentos no podrán ser mayores al 10%. Las Partes acuerdan que si dicho incremento sea superior al 16%, Las Partes se reunirán y determinarán de común acuerdo el monto de la renta.');
